test('Books bounded diagnostic: passed wrong identity uninitialized and throwing retention never replace error',async()=>{for(const patch of [{status:'passed'},{status:'skipped'},{project:{name:'books-mobile'}},{title:'other',titlePath:['other']},{file:'other.spec.ts'},{retry:1},{repeatEachIndex:1}]){const c=await booksCaptureCase('success',patch);assert.equal(c.evaluates,0);assert.equal(c.info.errors.length,1);}const h=await booksHarness(),info=booksInfo(),original=info.errors[0];await h.captureBooksDiagnostic({evaluate(){assert.fail('uninitialized capture');}},info);assert.equal(info.errors.length,1);Object.freeze(info.errors);assert.doesNotThrow(()=>h.retainBooksDiagnostic(info,booksSnapshot()));assert.strictEqual(info.errors[0],original);});

